    }).catch

fetcher(`${REC_URL}${endpoint}`, { credentials: 'include' })
      .then((r) => r.json())
      .then((json) => {
        if (cancelled) return;
        const list: Story[] = json?.success ? json.data?.stories || [] : [];
        setStories(list);
        if (list.length) send('impression', list.slice(0, 12).map((s) => s.id));
      })
      .catch
